/* ===== 底栏部分 ===== */
:root {
  /* 底栏背景透明 */
  --input-area-bg: transparent;
  --input-area-border-top: transparent;

  /* 按钮图标 */
  --plus-btn-icon: url('https://nos.netease.com/ysf/f782e379c0505b3263ff6c9da7de466f.gif');
  --sticker-btn-icon: url('https://nos.netease.com/ysf/409b5a93f4572ab9f5b575520d66146d.gif');
  --ai-btn-icon: url('https://nos.netease.com/ysf/cff9bb039011cfc77dca1d3fa15914bc.gif');
  --send-btn-icon: url('https://nos.netease.com/ysf/e02edada1097dae86a53ed1c8beb8820.gif')

  /* 输入框样式（透明） */
  --input-box-bg: transparent;
  --input-box-color: #262626;
  --input-box-placeholder: transparent;
  --input-box-radius: 24px;
  --input-box-padding: 10px 18px;
  --input-box-font-size: 15px;
  --input-box-border: 1px solid rgba(0, 0, 0, 0.1);
  --input-box-blur: none;
  --input-box-shadow: none;
  --input-caret-color: #0095f6;

  /* 发送按钮 */
  --send-btn-bg: transparent;
  --send-btn-color: #0095f6;
  --send-btn-size: auto;

  /* 加号按钮 */
  --plus-btn-bg: transparent;
  --plus-btn-color: #262626;
  --plus-btn-size: 24px;
}

/* 输入框胶囊外框透明 */
.input-action-bar-custom {
  margin-left: 12px !important;
  margin-right: 12px !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  position: relative !important;
}

/* 输入框下方纯横线（无弧线） */
.input-action-bar-custom::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: rgba(0, 0, 0, 0.12);
