/* ================================================
   文字图片美化   ================================================ */

/* 加载自定义字体 */
@font-face {
  font-family: 'PolaroidFont';
  src: url('https://yexingphoto.pages.dev/file/1PTIwCyB.ttf') format('truetype');
  font-weight: normal;
  font-style: normal;
  font-display: swap;
}

/* 拍立得外框 */
.msg-me .msg-sim-card,
.msg-them .msg-sim-card {
  width: 180px !important;
  height: 120px !important;

  background: #ffffff !important;
  padding: 6px 6px 20px 6px !important;

  border-radius: 3px !important;
  transform: rotate(-2deg) !important;
  transform-origin: center center !important;

  box-shadow: 
    0 0 0 1px #666666,
    0 4px 12px rgba(0, 0, 0, 0.15),
    inset 0 0 0 1px rgba(0, 0, 0, 0.06),
    inset 0 2px 4px rgba(255, 255, 255, 0.5) !important;

  position: relative !important;
  overflow: visible !important;

  border: none !important;
  aspect-ratio: auto !important;
}

/* 悬停回正 */
.msg-me .msg-sim-card:hover,
.msg-them .msg-sim-card:hover {
  transform: rotate(0deg) scale(1.03) !important;
  transition: all 0.3s ease !important;
  box-shadow: 
    0 0 0 1px #666666,
    0 6px 20px rgba(0, 0, 0, 0.2),
    inset 0 0 0 1px rgba(0, 0, 0, 0.06),
    inset 0 2px 4px rgba(255, 255, 255, 0.5) !important;
}

/* 隐藏内部所有原生内容 */
.msg-me .msg-sim-card *,
.msg-them .msg-sim-card * {
  display: none !important;
}

/* ========== 照片区域 + 黑色细边框（横屏·Android兼容版） ========== */

/* --- 照片本体：完整显示，不被裁剪 --- */
.msg-me .msg-sim-card::after,
.msg-them .msg-sim-card::after {
  content: '' !important;
  display: block !important;
  position: absolute !important;
  top: 6px !important;
  left: 6px !important;
  right: 6px !important;
  bottom: 22px !important;

  background-image: url('https://nos.netease.com/ysf/261c45e3cee8c2f93df0397b524085e7.jpeg') !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;

  border-radius: 1px !important;

  /* 黑色细边框 */
  outline: 1px solid #666666 !important;
  outline-offset: -1px !important;

  box-shadow: inset 0 0 0 1px #666666 !important;
}

/* ========== 底部文字（跟随倾斜） ========== */
.msg-bubble-container:has(.msg-sim-card) {
  position: relative !important;
  transform: rotate(-2deg) !important;
  transform-origin: center center !important;
}

/* 文字 */
.msg-bubble-container:has(.msg-sim-card)::before {
  content: '我这么萌你不炸了么O.o' !important;
  display: block !important;
  position: absolute !important;
  bottom: 4px !important;
  left: 50% !important;
  transform: translateX(-50%) !important;

  font-family: 'PolaroidFont', 'Courier New', Georgia, serif !important;
  font-size: 7px !important;
  color: #888888 !important;
  letter-spacing: 0.5px !important;
  white-space: nowrap !important;

  z-index: 5 !important;
  pointer-events: none !important;
}

/* 清除其他气泡容器装饰 */
.msg-me:has(.msg-sim-card),
.msg-them:has(.msg-sim-card) {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}


