/* 当气泡内只有图片或表情时，强制气泡透明、无边框、无背景 */
.msg-image-wrapper,
.bubble-me-custom:has(img:only-child),
.bubble-them-custom:has(img:only-child),
.bubble-me-custom:has(> .emoji-only:only-child),
.bubble-them-custom:has(> .emoji-only:only-child) {
 background: transparent !important;
 border: none !important;
 box-shadow: none !important;
 padding: 0 !important;
}

/* =========================================
   顶栏深度定制
========================================= */

:root {
  /* ⬇️【标注：调整 顶栏整体高度 的地方】⬇️ */
  --chat-header-height: 100px; 
  --chat-header-bg: #ffffff; /* 顶栏背景颜色 */

  /* ⬇️【标注：调整 头像大小 和 阴影 的地方】⬇️ */
  --chat-header-avatar-size: 55px; /* 头像大小（宽度和高度） */
  --chat-header-avatar-shadow: 0 4px 15px rgba(0, 0, 0, 0.2); /* 头像底阴影 */

  /* ⬇️【标注：调整 三个按钮方框 统一大小 的地方】⬇️ */
  --btn-w: 75px;          /* 方框宽度 */
  --btn-h: 28px;          /* 方框高度 */
  --btn-y: 65px;          /* 距离顶部的统一距离（上下位置：数值越大越靠下） */

  /* ⬇️【标注：调整 三个按钮方框 左右间距/横向位置 的地方】⬇️ */
  --btn1-x: 60px;         /* PHONE 左右位置（数值越大越靠右） */
  --btn2-x: 170px;        /* VIDEO 左右位置 */
  --btn3-x: 275px;        /* CONTROL 左右位置 */


  /* =========================================
     🌟【官方原生的右上角自订装饰贴图 1】
  ========================================= */
  --chat-header-deco-1-image: url('https://s3.bmp.ovh/2026/07/16/xWHriicW.png'); /* 贴图链接 */

  /* ⬇️【标注：调整贴图 宽度、高度、缩放 比例的地方】⬇️ */
  --chat-header-deco-1-width: 90px;       /* 贴图宽度 */
  --chat-header-deco-1-height: 35px;      /* 贴图高度 */
  --chat-header-deco-1-size: contain;     /* 保持比例缩放 */

  /* ⬇️【标注：调整贴图 左右和上下位置 的地方】⬇️ */
  --chat-header-deco-1-top: 15px;         /* 距离顶栏顶部的距离（数值越大越靠下） */
  --chat-header-deco-1-right: 15px;       /* 距离右侧边缘的距离（数值越大越靠左） */
  --chat-header-deco-1-left: auto;        /* 保持 auto 即可 */
  --chat-header-deco-1-bottom: auto;      /* 保持 auto 即可 */

  /* ⬇️【标注：调整贴图 其他特殊效果（旋转/透明度/层级）的地方】⬇️ */
  --chat-header-deco-1-transform: none;   /* 可以填旋转度数，例如 rotate(-10deg) */
  --chat-header-deco-1-opacity: 1;        /* 透明度：0 ~ 1 之间 */
  --chat-header-deco-1-z: 1002;           /* 图层高度，确保在最顶层 */
  --chat-header-deco-1-repeat: no-repeat;

  /* 保持其他原生的装饰层不显示 */
  --chat-header-deco-2-image: none;
  --chat-header-deco-3-image: none;
  --chat-header-deco-4-image: none;
  --chat-header-deco-5-image: none;
  --chat-header-deco-6-image: none;
}

/* 释放顶栏限制，允许内部元素溢出显示 */
.chat-header-custom,
.chat-detail-screen .glass-header,
.header-profile-section {
    position: relative !important;
    overflow: visible !important;
}

.chat-detail-screen .glass-header {
    align-items: flex-start !important;
    padding-top: 15px !important; 
}

/* 隐藏原本的在线状态副标题 */
.chat-header-subtitle { display: none !important; }


/* =========================================
   【新增标注】1. 返回键（左侧箭头 < ）的位置调整
========================================= */
.chat-detail-screen .header-btn-back {
    position: absolute !important;
    /* ⬇️【标注：单独调整“返回键”上下和左右位置的地方】⬇️ */
    top: -10px !important;    /* 距离顶栏顶部的距离（数值越大越靠下） */
    left: 15px !important;   /* 距离屏幕左侧的距离（数值越大越靠右） */
    z-index: 1001 !important;
}


/* =========================================
   【新增标注】2. 头像 的位置和大小调整
========================================= */
.chat-detail-screen .header-avatar-container {
    position: absolute !important;
    /* ⬇️【标注：单独调整“大头像”上下和左右位置的地方】⬇️ */
    top: -35px !important;    /* 距离顶栏顶部的距离（数值越大越靠下） */
    left: 15px !important;   /* 距离左侧的距离（数值越大越靠右，注意不要和返回键重叠） */

    /* 大小和阴影自动读取最上面 :root 里的变量 */
    width: var(--chat-header-avatar-size) !important;
    height: var(--chat-header-avatar-size) !important;
    box-shadow: var(--chat-header-avatar-shadow) !important;
    z-index: 99 !important;
}


/* =========================================
   【新增标注】3. 聊天消息区域整体下移（防止被顶栏挡住）
========================================= */
/* 🌟重要：因为我们的顶栏变高了，如果不把消息区域往下推，前几条聊天记录会被顶栏挡住 */
.chat-message-list-custom {
    /* ⬇️【标注：调整聊天记录整体往下推的距离】⬇️ */
    /* 这个值一般建议比你的顶栏高度（--chat-header-height）大 15px-20px 左右 */
    padding-top: 135px !important; 
}


/* =========================================
   4. 渐变圆形条 & 昵称
========================================= */
.chat-detail-screen .chat-header-title {
    background: linear-gradient(to right, rgba(160,160,160,0) 20%, rgba(150,150,150,0.6) 100%) !important;
    border-radius: 50px !important; 
    color: #ffffff !important; 

    display: flex !important;
    justify-content: flex-end !important; 
    align-items: center !important;
    z-index: 10 !important;

    /* ⬇️【标注：调整昵称渐变条 宽度、高度、字号 的地方】⬇️ */
    width: 220px !important;  
    height: 30px !important;  
    font-size: 14px !important; 
    padding-right: 20px !important; /* 名字距离右边圆角的距离 */

    /* ⬇️【标注：调整昵称渐变条 上下和左右位置 的地方】⬇️ */
    position: absolute !important;
    top: -18px !important;   /* 距离顶栏顶部的距离（数值越大越靠下） */
    left: 15px !important;  /* 距离屏幕左侧的距离（数值越大越靠右） */
}


/* =========================================
   5. 视觉层（底层）：100%强制画出 3 个灰色方框
========================================= */

/* 1号方框：PHONE */
.chat-detail-screen .glass-header::before {
    content: "PHONE" !important;
    position: fixed !important; left: var(--btn1-x) !important; top: var(--btn-y) !important;
    width: var(--btn-w) !important; height: var(--btn-h) !important;
    background-color: #E9E9E9 !important; border-radius: 6px !important;
    color: #555555 !important; font-size: 11px !important; font-weight: bold !important; letter-spacing: 1px !important;
    display: flex !important; align-items: center !important; justify-content: center !important;
    z-index: 900 !important; pointer-events: none !important;
}

/* 2号方框：VIDEO */
.chat-detail-screen .glass-header::after {
    content: "VIDEO" !important;
    position: fixed !important; left: var(--btn2-x) !important; top: var(--btn-y) !important;
    width: var(--btn-w) !important; height: var(--btn-h) !important;
    background-color: #E9E9E9 !important; border-radius: 6px !important;
    color: #555555 !important; font-size: 11px !important; font-weight: bold !important; letter-spacing: 1px !important;
    display: flex !important; align-items: center !important; justify-content: center !important;
    z-index: 900 !important; pointer-events: none !important;
}

/* 3号方框：CONTROL */
.header-profile-section::after {
    content: "CONTROL" !important;
    position: fixed !important; left: var(--btn3-x) !important; top: var(--btn-y) !important;
    width: var(--btn-w) !important; height: var(--btn-h) !important;
    background-color: #E9E9E9 !important; border-radius: 6px !important;
    color: #555555 !important; font-size: 11px !important; font-weight: bold !important; letter-spacing: 1px !important;
    display: flex !important; align-items: center !important; justify-content: center !important;
    z-index: 900 !important; pointer-events: none !important;
}


/* =========================================
   6. 触控层（顶层）：真实的可点击按钮（fixed绝对对齐）
========================================= */

/* 隐藏真实按钮的默认图标 */
.header-btn-phone svg, .header-btn-video svg, .header-btn-info svg {
    display: none !important;
}

/* 真实按钮设为 fixed 透明点击薄膜，完美覆盖在灰色方框正上方 */
.header-btn-phone, .header-btn-video, .header-btn-info {
    display: block !important;
    position: fixed !important; 
    top: var(--btn-y) !important;
    width: var(--btn-w) !important; 
    height: var(--btn-h) !important;

    background: transparent !important;
    border: none !important; margin: 0 !important; padding: 0 !important;
    transform: none !important; 

    opacity: 0.01 !important; /* 几乎完全透明，但保留实体触控属性 */
    z-index: 9999 !important; /* 保证浮在绝对最上方，确保可点 */
    cursor: pointer !important;
}

/* 透明点击实体位置与方框完全重合 */
.header-btn-phone { left: var(--btn1-x) !important; }
.header-btn-video { left: var(--btn2-x) !important; }
.header-btn-info  { left: var(--btn3-x) !important; }

/* 禁用系统内置 of 按钮多余样式干扰 */
.header-action-btn { background: none !important; box-shadow: none !important; border: none !important; }
:root {
  /* ================================================
     1. 基础气泡定制（我方/对方颜色与缩放）
     ================================================ */
  --bubble-me-bg: #E9E9E9;
  --bubble-me-border: none;
  --bubble-me-color: #262626;
  --bubble-me-font-size: 14px;
  --bubble-me-padding: 8px 12px;
  --bubble-me-line-height: 1.35;

  --bubble-them-bg: #ffffff;
  --bubble-them-border: 1px solid #E9E9E9;
  --bubble-them-color: #262626;
  --bubble-them-font-size: 14px;
  --bubble-them-padding: 8px 12px;
  --bubble-them-line-height: 1.35;

  --chat-message-max-width: 72%;

  /* ================================================
     2. 语音气泡等比例缩小
     ================================================ */
  --voice-play-btn-size: 22px;         /* 播放按钮缩小 */
  --voice-waveform-height: 22px;       /* 波形高度缩小 */
  --voice-duration-size: 9px;          /* 时间数字缩小 */
  --voice-bar-max-width: 2.5px;
  --voice-waveform-gap: 1.5px;

  /* 注意：这里必须让按钮渲染（不要设为none），我们将在下方用物理覆盖来实现全气泡点击 */
  --voice-toggle-display: flex;        

  /* 语音辨识文字样式调整 */
  --voice-transcription-bg: transparent; /* 融入底色 */
  --voice-transcription-padding: 8px 0 0 0;
  --voice-transcription-margin-top: 6px;
  --voice-transcription-size: 13px;      /* 辨识文字大小 */
}

/* ================================================
   3. 全气泡点击展开交互黑魔法 (Full-Bubble Click)
   ================================================ */
/* 确保语音消息外层容器是定位基准 */
.voice-msg {
  position: relative !important;
}

/* 核心：将“展开文字”按钮透明化并撑满整个气泡 */
.voice-transcription-toggle {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  width: 100% !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0 !important;

  opacity: 0 !important;             /* 100% 透明，完全看不见按钮和文字 */
  background: transparent !important; /* 背景透明 */
  border: none !important;
  cursor: pointer !important;
  z-index: 5 !important;              /* 盖在气泡、波形和时间文字的上方 */
}

/* 关键：把播放按钮和下载按钮提到最上层，防止被透明层挡住导致无法播放 */
.voice-play-btn,
.voice-download-btn {
  position: relative !important;
  z-index: 10 !important;             /* 确保层级高于透明点击层 */
}

/* 语音辨识文字上方加入 1px 虚线 */
.voice-transcription {
  border-top: 1px dashed rgba(0, 0, 0, 0.1) !important;
  margin-top: 8px !important;
  padding-top: 8px !important;
  position: relative !important;
  z-index: 10 !important;             /* 展开后的文字也要在最上层，防止阻挡二次点击收起 */
}


/* ================================================
   4. 贴图装饰容器（确保不被裁剪）
   ================================================ */
.bubble-me-custom, .bubble-deco-me,
.bubble-them-custom, .bubble-deco-them {
  position: relative !important;
  overflow: visible !important;
}

/* ================================================
   5. 我方气泡右上角贴图 (Me Bubble)
   ================================================ */
.bubble-me-custom::after {
  content: "";
  position: absolute;
  pointer-events: none;
  z-index: 20;                        /* 贴图层级提到最高 */
  background: url("https://s3.bmp.ovh/2026/07/16/wbsbVnJc.png") no-repeat center/contain;

  /* 大小 */
  width: 15px;
  height: 15px;
  /* 位置 */
  top: 1px;
  right: -4px;
  /* 旋转 */
  transform: rotate(-10deg);
}

/* ================================================
   6. 对方气泡左上角贴图 (Them Bubble)
   ================================================ */
.bubble-them-custom::before {
  content: "";
  position: absolute;
  pointer-events: none;
  z-index: 20;                        /* 贴图层级提到最高 */
  background: url("https://s3.bmp.ovh/2026/07/16/qE3Ssd1h.png") no-repeat center/contain;

  /* 大小 */
  width: 15px;
  height: 15px;
  /* 位置 */
  top: 2px;
  left: -9px;
  /* 旋转 */
  transform: rotate(10deg);
}
/* ================================================
   新增：引用消息气泡分离 + 模拟文字划掉（删除线）效果
   ================================================ */

/* 1. 隐藏气泡内部的默认引用块 */
.msg-reply-block {
  display: none !important;
}

/* 2. 启用并重置气泡下方独立的引用条（实现透明背景、无框） */
.msg-reply-block-detached {
  display: flex !important;
  background: transparent !important;       /* 透明背景 */
  box-shadow: none !important;              /* 移除阴影 */
  border: none !important;                  /* 移除边框/左边线 */
  padding: 4px 6px 0 6px !important;        /* 紧凑边距，紧贴在气泡下方 */
  margin-top: 2px !important;
}

/* 3. 隐藏引用的人名，只保留并直接显示引用的文本 */
.msg-reply-detached-name {
  display: none !important;
}

/* 4. 模拟文字被划掉的样子 */
.msg-reply-detached-text {
  text-decoration: line-through !important; /* 【核心】文字中间画横线 */
  text-decoration-color: rgba(38, 38, 38, 0.4) !important; /* 横线颜色与透明度（0.4为轻微淡化） */
  color: rgba(38, 38, 38, 0.5) !important;   /* 文字本身颜色淡化，使其更像被废弃的备注 */
  font-size: 11.5px !important;             /* 字体稍微缩小 */
  white-space: normal !important;           /* 允许多行折行 */
  letter-spacing: 0.5px !important;         /* 字距微调 */
}
/* ================== ★ 转账卡核心外框 (灰底白字版) ★ ================== */
.msg-transfer-card { 
    position: relative !important; 
    width: 240px !important; 
    height: 100px !important; 
    background-color: rgba(142, 142, 147, 0.65) !important;  /* 【修改】高级灰色半透明背景 */
    backdrop-filter: blur(20px) saturate(160%) !important; 
    border: 1px solid rgba(255, 255, 255, 0.25) !important;  /* 边框改为偏透明白 */
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.08) !important; 
    border-radius: 12px !important; 
    margin-top: 4px !important; 
    overflow: hidden !important; 
    display: block !important; 
    padding: 0 !important; 
    /* 【修改】SVG 图标颜色从 %23888888 改为 %23ffffff (纯白)，分割线改为白色半透明 */
    background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 40 40"><circle cx="20" cy="20" r="18" fill="none" stroke="%23ffffff" stroke-width="2.5"/><path d="M12 14h16m-4-4l4 4-4 4" fill="none" stroke="%23ffffff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><path d="M28 26H12m4-4l-4 4 4 4" fill="none" stroke="%23ffffff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>'), linear-gradient(rgba(255,255,255,0.2), rgba(255,255,255,0.2)) !important; 
    background-size: 36px 36px, 100% 1px !important; 
    background-repeat: no-repeat, no-repeat !important; 
    background-position: 12px 20px, 0 74px !important; 
}

/* 清除杂项背景 */
.msg-transfer-card * { 
    background-color: transparent !important; 
    box-shadow: none !important; 
    border: none !important; 
}

/* 隐藏自带的SVG图标、头像、原版副标题 */
.msg-transfer-card svg, 
.msg-transfer-card img, 
.transfer-icon-bg, 
.msg-transfer-subtitle { 
    display: none !important; 
}

/* ================== ★ 白色字：转账 (Label) ★ ================== */
.msg-transfer-label { 
    position: absolute !important; 
    top: 10px !important; 
    left: 60px !important; 
    font-size: 13px !important; 
    font-weight: 600 !important; 
    color: #ffffff !important;         /* 【修改】纯白 */
    -webkit-text-fill-color: #ffffff !important; 
    display: block !important; 
    visibility: visible !important; 
    z-index: 10 !important; 
}

/* ================== ★ 修复金额颜色，强制变白 ★ ================== */
/* 劫持所有主题变量 */
:root, .chat-detail-screen, .msg-transfer-card {
    --transfer-amount-color: #ffffff !important;           /* 【修改】纯白 */
    --transfer-me-amount-color: #ffffff !important;
    --transfer-them-amount-color: #ffffff !important;
    --transfer-success-amount-color: #ffffff !important;
    --transfer-rejected-amount-color: #ffffff !important;
    --transfer-expired-amount-color: #ffffff !important;
}

/* 只对父容器进行绝对定位排版，不碰子元素 */
.msg-transfer-amount {
    position: absolute !important; 
    top: 32px !important; 
    left: 60px !important; 
    display: block !important; 
    z-index: 10 !important; 
}

/* 给父容器及其内部所有的字符强行染色，彻底清除原系统自带的渐变底色 */
.msg-transfer-amount, 
.msg-transfer-amount * { 
    font-size: 22px !important; 
    font-weight: bold !important; 
    color: #ffffff !important;         /* 【修改】纯白 */
    background: none !important;                 
    -webkit-text-fill-color: #ffffff !important; 
    text-shadow: none !important;
}

/* ================== ★ 状态文字单行截断：绝杀“23小时后过期” ★ ================== */
.msg-transfer-status-text { 
    position: absolute !important; 
    top: 78px !important; 
    left: 60px !important; 
    font-size: 11px !important; 
    font-weight: 500 !important; 
    color: rgba(255, 255, 255, 0.00) !important;          /* 【修改】85%透明度的白色，增加层次感 */
    -webkit-text-fill-color: rgba(255, 255, 255, 0.85) !important;
    display: block !important; 
    z-index: 10 !important; 

    /* 🔪 核心物理截断：像切豆腐一样切掉第二行文字 */
    height: 14px !important;        
    line-height: 14px !important;   
    white-space: nowrap !important; 
    overflow: hidden !important;    
}

/* 如果过期文字是通过回车符 <br> 添加的，直接把它隐藏 */
.msg-transfer-status-text br { 
    display: none !important; 
}

/* 如果过期文字包在第二段 span 里，直接隐藏第二个及其以后的所有 span */
.msg-transfer-status-text > *:not(:first-child) {
    display: none !important;
}

/* 拦截独立出来的过期 Class 节点 */
.msg-transfer-card [class*="expire"],
.msg-transfer-card [class*="time"],
.msg-transfer-card [class*="date"] {
    display: none !important;
}

/* 隐藏你之前加的占位伪元素 */
.msg-transfer-card::before,
.msg-transfer-card::after { 
    display: none !important; 
}

/* ================================================
   底部提示条统一为灰白色系 (以角色身份发送 / 旁白模式)
   ================================================ */
.chat-detail-screen {
  /* 1. “以角色身份发送” 状态条 */
  --sendas-char-bg: #ffffff;                 /* 背景色：纯白（或者您可以改为 #E9E9E9） */
  --sendas-char-color: #262626;              /* 文字色：深灰色（与气泡文字一致） */
  --sendas-char-border: 1px solid #E9E9E9;   /* 边框色：浅灰色（与对方气泡边框一致） */

  /* 2. “旁白模式” 状态条 (同步颜色，防患于未然) */
  --sendas-narration-bg: #ffffff;
  --sendas-narration-color: #262626;
  --sendas-narration-border: 1px solid #E9E9E9;

  /* 3. 通用设置：右侧关闭按钮 (X) 和圆角 */
  --sendas-close-color: #888888;             /* 关闭按钮 (X) 改为中灰色 */
  --sendas-bar-radius: 12px;                 /* 胶囊圆角，与气泡更搭 */
}
/* ================================================
   新增：翻译气泡分离 + 透明底 + 下划线效果
   ================================================ */

/* 1. 隐藏气泡内部默认的翻译区域 */
.msg-translation-wrapper {
  display: none !important;
}

/* 2. 启用气泡下方独立的翻译块 */
.msg-translation-detached {
  display: block !important;
  margin-top: 6px !important;              /* 紧贴在原气泡下方 */
  max-width: var(--chat-message-max-width, 72%) !important;
  width: fit-content !important;
}

/* 3. 区分左右：我方翻译靠右，对方翻译靠左 */
.msg-translation-detached-me {
  align-self: flex-end !important;
}
.msg-translation-detached-them {
  align-self: flex-start !important;
}

/* 4. 核心：透明背景、文字下方加下划线 */
.msg-translation-detached-content {
  background: transparent !important;       /* 文字背景完全透明 */
  box-shadow: none !important;              /* 移除阴影 */
  border: none !important;                  /* 移除原本的气泡边框 */
  border-radius: 0 !important;              /* 移除气泡圆角 */

  /* ────────────────【 实现下划线效果 】──────────────── */
  border-bottom: 1px solid #CCCCCC !important; /* 划线颜色（可改为 #262626 或其他色系） */
  padding: 2px 4px !important;              /* 左右稍微扩宽一点，让下划线超出文字边缘更美观 */

  /* 文字样式（在横线上方显示） */
  color: #262626 !important;                /* 文字颜色，同步深灰 */
  font-size: 13.5px !important;             /* 翻译字体微调 */
  line-height: 1.4 !important;
  display: inline-block !important;
}

/* 5. 抹除之前可能残留的微信/系统自带的水印、对勾和多余伪元素 */
.msg-translation-detached-content::before,
.msg-translation-detached-content::after {
  display: none !important;
}
/* ================================================
   修改：分离翻译文字颜色改为灰色
   ================================================ */
.msg-translation-detached-content {
  color: #888888 !important;                /* 文字颜色改为灰色 */
  -webkit-text-fill-color: #888888 !important;
  border-bottom: 1px solid #DDDDDD !important; /* 下划线也同步调整为更柔和的浅灰色 */
}
/* ================================================
   修改：调整翻译文字的行距与换行宽度
   ================================================ */

.msg-translation-detached {
  /* ────────────────【 调整换行的长度（宽度限制） 】──────────────── */
  /* 数值越大，每行能装的字越多，越不容易换行。
     可以设为百分比（如 80%）或固定像素（如 260px）。 */
  max-width: 90% !important;                /* 【换行最大宽度】：默认从 72% 放宽到 80% */
}
/* ================================================
   修改：调整翻译文字距离上方消息气泡的间距
   ================================================ */

.msg-translation-detached {
  /* ────────────────【 调整距离气泡的垂直间距 】──────────────── */
  /* 数值越大，翻译文字距离上方聊天气泡就越远。
     您可以根据喜好自由微调该数值（如 8px, 12px, 16px）。 */
  margin-top: 2px !important;              /* 【间距大小】：从默认 6px 调大至 12px */
}
/* ================================================
   新增：气泡发送渐显入场动画 (Bubble Fade-In)
   ================================================ */
@keyframes bubbleFadeIn {
  from {
    opacity: 0;
    transform: translateY(10px);  /* 【渐显起点位置】：从下方10px处升起 */
  }
  to {
    opacity: 1;
    transform: translateY(0);     /* 回归正常位置 */
  }
}

/* 应用动画到所有的消息行 */
.msg-bubble-wrapper,
.msg-plain,
.msg-translation-detached,
.msg-reply-block-detached {
  animation: bubbleFadeIn 0.35s cubic-bezier(0.1, 0.8, 0.25, 1) forwards !important;
  /* 0.35s 是动画持续时间，数值越小速度越快 */
}
/* ================================================
  AI 等待气泡
   ================================================ */

/* 1. 物理清场：隐藏气泡内部的【所有】默认结构，防止多余的容器捣乱排版 */
.nuo-typing-bubble * {
  display: none !important;
}

/* 2. 气泡本体：同步对方气泡色系，并强制开启 flex 居中 */
.nuo-typing-bubble {
  /* ────────────────【 同步对方气泡样式 】──────────────── */
  background: #ffffff !important;             /* 同步：纯白底色 */
  border: 1px solid #E9E9E9 !important;       /* 同步：1px 浅灰边框 */
  border-radius: var(--bubble-them-radius, 16px) !important; /* 同步圆角 */
  padding: 8px 14px !important;               /* 与普通气泡一致的内边距 */

  /* ────────────────【 防塌陷安全锁 】───────────────── */
  display: flex !important;                   /* 启用 Flex 布局 */
  align-items: center !important;             /* 确保内部文字绝对垂直居中 */
  justify-content: center !important;         /* 确保内部文字绝对水平居中 */
  min-width: 52px !important;                 /* 【安全锁】：确保气泡绝不缩成迷你点 */
  min-height: 32px !important;                /* 【安全锁】：确保高度正常 */
  width: auto !important;
  height: auto !important;
  box-shadow: none !important;
}

/* 3. 在干净的气泡内部注入 "o.O" 文本，并加入呼吸微颤动画 */
.nuo-typing-bubble::after {
  content: "o.O" !important;                  /* 注入颜表情 */
  display: block !important;

  /* ────────────────【 同步对方文字样式 】───────────────── */
  font-family: "Courier New", monospace !important; /* 等宽字体更可爱 */
  font-size: 14px !important;                 /* 同步对方：字号 14px */
  color: #262626 !important;                  /* 同步对方：文字颜色深灰 */
  font-weight: 600 !important;                 /* 略微加粗更加明显 */
  line-height: 1 !important;
  letter-spacing: 1px !important;             /* 稍微拉开字母间距 */

  /* 专属动画 */
  animation: oOSimpleBounce 1.4s ease-in-out infinite !important; 
}

/* 4. 专属微幅呼吸弹跳动画 */
@keyframes oOSimpleBounce {
  0%, 100% {
    transform: translateY(0);
    opacity: 0.8;
  }
  50% {
    transform: translateY(-2px) scale(1.05);  /* 向上微跳 2px，并轻微放大 */
    opacity: 1;
  }
}
/* ================================================
   1. 底栏整体：透明度与上下位移
   ================================================ */
.input-area-custom {
  background: transparent !important;
  border-top: none !important;
  box-shadow: none !important;

  /* ────────────────【 调整底栏整体上下移动 】──────────────── */
  /* 负数往上漂移（例如 -10px），正数往下移动 */
  transform: translateY(-20px) !important; 
}

.input-row-wrapper {
  background: transparent !important;
  border: none !important;
}

/* ================================================
