  border: none !important;
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

.input-btn-ai svg { display: none !important; }

.input-btn-ai::after {
  content: "" !important;
  display: block !important;
  background: url('https://s3.bmp.ovh/2026/07/16/D6k9affK.png') no-repeat center/contain !important;

