/* ================================================
   6. 发送按钮：配合高度微调
   ================================================ */
.send-btn-custom {
  --send-btn-size: 28px;      /* 稍微缩小发送按钮以适配矮输入框 */
  margin-left: 4px !important;
}
/* === 新增：光标颜色、打字位置与禁止旋转 === */

/* 1. 调整光标颜色 & 打字起始位置 */
.input-box-custom {
  /* 调整光标颜色 */
  caret-color: #888888 !important; 

  /* 调整打字起始位置：修改最后那个 8px，数值越大文字越往右移 */
  padding: 5px 8px 0px 8px !important; 
}

/* 2. 禁止加号按钮点击旋转（锁定 0 度） */
.input-btn-plus, 
.input-btn-plus.open, 
.input-btn-plus:active,
.input-btn-plus::after {
  transform: rotate(0deg) !important; /* 强制锁定 0 度 */
  transition: none !important;        /* 彻底关掉旋转过渡动画 */
}
/* ================================================
   新增：隐藏默认占位符并替换为 ✩⁺첫사랑맛˖˚
   ================================================ */

/* 1. 彻底隐藏系统默认的 placeholder 提示文字 */
.input-box-custom::placeholder {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
  opacity: 0 !important;
}

/* 2. 注入您的专属个性占位符：✩⁺첫사랑맛˖˚ */
.input-action-bar-custom:has(.input-box-custom:placeholder-shown)::before {
  content: "✩⁺첫사랑맛˖˚" !important;
  position: absolute !important;
  left: 48px !important;                      /* 完美对齐您的打字起始位置 */
  top: 19px !important;                       /* 垂直对齐首行文字 */
  transform: translateY(-50%) !important;
  color: #888888 !important;                  /* 保持统一的灰色系 */
  font-size: 13px !important;
  pointer-events: none !important;            /* 允许鼠标/手指穿透点击，不阻挡输入框聚焦 */
  opacity: 0.75 !important;
}
/* ================================================
   新增：气泡上下间隔距离精确调节
   ================================================ */

/* 1. 【相同发送者】连续发消息时的气泡间距 */
.msg-bubble-wrapper.is-first,
.msg-bubble-wrapper.is-mid {
  /* ────────────────【 调整同发言人连续气泡间距 】──────────────── */
  /* 数值越小，自己连续发的几条气泡贴得越紧。默认建议 2px ~ 6px */
  margin-bottom: 5px !important;  
}

/* 2. 【不同发送者】换人说话，或者一句话结束后的整组间距 */
.msg-bubble-wrapper.is-last,
.msg-bubble-wrapper.is-single {
  /* ────────────────【 调整换人说话时的气泡间距 】──────────────── */
  /* 数值越大，你和对方对话之间的换行空隙越明显，视觉排版极佳。默认建议 16px ~ 24px */
  margin-bottom: 20px !important; 
}
/* =========================================
   特殊消息（图片/视频/卡片等）自动隐藏装饰
========================================= */

/* 当气泡内包含图片、视频、图片容器、转账卡片、位置卡片、长图卡片、礼物盒时，隐藏所有装饰 */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::before,
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::after,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::before,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container)::after {
  display: none !important;
}

/* ================================================
 * 消息间距微调
 * ================================================ */

.chat-message-list-custom .msg-bubble-container {
  margin-bottom: 1px !important;
}

.bubble-me-custom.first,
.bubble-them-custom.first {
  margin-top: 5px;
}
/* 当气泡内包含：图片(含表情包)、视频、图片容器、转账卡片、位置卡片、长图卡片、礼物盒 时，强制背景透明并去掉内边距 */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container),
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container) {
  background-color: transparent !important;
  background: transparent !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
}
/* 当气泡内包含图片、视频、转账卡片、位置卡片、长图卡片、礼物盒、电话卡片时，隐藏装饰贴图（::before 和 ::after） */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"])::before,
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"])::after,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"])::before,
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container, .msg-phone-card, [class*="call"], [class*="phone"])::after {
  display: none !important;
}

/* =========================================
   顶栏深度定制
========================================= */

:root {
  /* ⬇️【标注：调整 顶栏整体高度 的地方】⬇️ */
  --chat-header-height: 100px; 
  --chat-header-bg: #ffffff; /* 顶栏背景颜色 */

  /* ⬇️【标注：调整 头像大小 和 阴影 的地方】⬇️ */
  --chat-header-avatar-size: 55px; /* 头像大小（宽度和高度） */
  --chat-header-avatar-shadow: 0 4px 15px rgba(0, 0, 0, 0.2); /* 头像底阴影 */

  /* ⬇️【标注：调整 三个按钮方框 统一大小 的地方】⬇️ */
  --btn-w: 75px;          /* 方框宽度 */
  --btn-h: 28px;          /* 方框高度 */
  --btn-y: 65px;          /* 距离顶部的统一距离（上下位置：数值越大越靠下） */

  /* ⬇️【标注：调整 三个按钮方框 左右间距/横向位置 的地方】⬇️ */
  --btn1-x: 60px;         /* PHONE 左右位置（数值越大越靠右） */
  --btn2-x: 170px;        /* VIDEO 左右位置 */
  --btn3-x: 275px;        /* CONTROL 左右位置 */


  /* =========================================
     🌟【官方原生的右上角自订装饰贴图 1】
  ========================================= */
  --chat-header-deco-1-image: url('https://s3.bmp.ovh/2026/07/16/xWHriicW.png'); /* 贴图链接 */

  /* ⬇️【标注：调整贴图 宽度、高度、缩放 比例的地方】⬇️ */
  --chat-header-deco-1-width: 90px;       /* 贴图宽度 */
  --chat-header-deco-1-height: 35px;      /* 贴图高度 */
  --chat-header-deco-1-size: contain;     /* 保持比例缩放 */

  /* ⬇️【标注：调整贴图 左右和上下位置 的地方】⬇️ */
  --chat-header-deco-1-top: 15px;         /* 距离顶栏顶部的距离（数值越大越靠下） */
  --chat-header-deco-1-right: 15px;       /* 距离右侧边缘的距离（数值越大越靠左） */
  --chat-header-deco-1-left: auto;        /* 保持 auto 即可 */
  --chat-header-deco-1-bottom: auto;      /* 保持 auto 即可 */

  /* ⬇️【标注：调整贴图 其他特殊效果（旋转/透明度/层级）的地方】⬇️ */
  --chat-header-deco-1-transform: none;   /* 可以填旋转度数，例如 rotate(-10deg) */
  --chat-header-deco-1-opacity: 1;        /* 透明度：0 ~ 1 之间 */
  --chat-header-deco-1-z: 1002;           /* 图层高度，确保在最顶层 */
  --chat-header-deco-1-repeat: no-repeat;

  /* 保持其他原生的装饰层不显示 */
  --chat-header-deco-2-image: none;
  --chat-header-deco-3-image: none;
  --chat-header-deco-4-image: none;
  --chat-header-deco-5-image: none;
  --chat-header-deco-6-image: none;
}

/* 释放顶栏限制，允许内部元素溢出显示 */
.chat-header-custom,
.chat-detail-screen .glass-header,
.header-profile-section {
    position: relative !important;
    overflow: visible !important;
}

.chat-detail-screen .glass-header {
    align-items: flex-start !important;
    padding-top: 15px !important; 
}

/* 隐藏原本的在线状态副标题 */
.chat-header-subtitle { display: none !important; }


/* =========================================
   【新增标注】1. 返回键（左侧箭头 < ）的位置调整
========================================= */
.chat-detail-screen .header-btn-back {
    position: absolute !important;
    /* ⬇️【标注：单独调整“返回键”上下和左右位置的地方】⬇️ */
    top: -10px !important;    /* 距离顶栏顶部的距离（数值越大越靠下） */
    left: 15px !important;   /* 距离屏幕左侧的距离（数值越大越靠右） */
    z-index: 1001 !important;
