  transition: none !important;       /* 拔除过渡动画，防止点击时发生偏移或抖动 */
  animation: none !important;        /* 彻底消除任何旋转动画绑定 */
}
/* ==========================================================================
   新增：提示栏（旁白/以对方发送）白色发光化 + 输入框文字上下位置微调
   ========================================================================== */

:root {
