}
/* ==========================================================================
   全新升级：全屏五轨拟真流星雨（视口静止锁定 + 硬件加速）
   ========================================================================== */

/* === 1. 统一格式化：全屏5大流星发射器 === */
.chat-detail-screen::before,
.chat-detail-screen::after,
.chat-messages-area::before,
.chat-messages-area::after,
.header-profile-section::before {
  content: "" !important;
  position: fixed !important;       /* 👈 核心：视口锁定，滚动聊天时流星绝不跟着跑 */
  height: 1.2px !important;          /* 极细精致流星轨迹 */
  background: linear-gradient(to right, transparent, rgba(255, 255, 255, 0.4), #ffffff) !important;
  filter: drop-shadow(0 0 5px rgba(255, 255, 255, 0.95)) !important;

  pointer-events: none !important;   /* 穿透点击 */
  z-index: 0 !important;             /* 锁在最底层 */
  opacity: 0;
  will-change: transform, opacity;   /* 强行开启显卡硬件加速，防止滚动掉帧 */
}

/* === 2. 五大流星轨道独立定位与速度参数 === */

/* 【流星 1 号】：高空·快速小流星 */
.chat-detail-screen::before {
  top: 8% !important;
  right: -150px !important;
  width: 80px !important;
  animation: meteor-track-1 6s linear infinite !important;
}

/* 【流星 2 号】：中高空·经典长尾流星 */
.chat-detail-screen::after {
  top: 24% !important;
  right: -150px !important;
  width: 110px !important;
  animation: meteor-track-2 8s linear infinite !important;
  animation-delay: 1.8s !important; /* 延迟滑出，错开时间 */
}

/* 【流星 3 号】：中空·中速流星 */
.chat-messages-area::before {
  content: "" !important;
  top: 42% !important;
  right: -150px !important;
  width: 95px !important;
  animation: meteor-track-3 7s linear infinite !important;
  animation-delay: 3.2s !important;
}

/* 【流星 4 号】：低空·超速闪烁流星 */
.chat-messages-area::after {
  content: "" !important;
  top: 58% !important;
  right: -150px !important;
  width: 70px !important;
  animation: meteor-track-4 5s linear infinite !important;
  animation-delay: 0.8s !important;
}

/* 【流星 5 号】：超低空·慢速优雅长流星 */
.header-profile-section::before {
  content: "" !important;
  top: 76% !important;
  right: -150px !important;
  width: 140px !important;
  animation: meteor-track-5 11s linear infinite !important;
  animation-delay: 4.5s !important;
}

/* === 3. 五大轨道独立拟真动画（各流星的角度和距离均有微调，极其自然） === */

/* 轨道 1 动画：角度 -33° */
@keyframes meteor-track-1 {
  0% { transform: translate(0, 0) rotate(-33deg) scale(0); opacity: 0; }
  4% { opacity: 1; transform: translate(-350px, 227px) rotate(-33deg) scale(1); }
  8% { opacity: 0; transform: translate(-700px, 454px) rotate(-33deg) scale(0); }
  100% { transform: translate(-700px, 454px) rotate(-33deg) scale(0); opacity: 0; }
}

/* 轨道 2 动画：角度 -36° */
@keyframes meteor-track-2 {
  0% { transform: translate(0, 0) rotate(-36deg) scale(0); opacity: 0; }
  5% { opacity: 1; transform: translate(-400px, 290px) rotate(-36deg) scale(1.1); }
  10% { opacity: 0; transform: translate(-800px, 580px) rotate(-36deg) scale(0); }
  100% { transform: translate(-800px, 580px) rotate(-36deg) scale(0); opacity: 0; }
}

/* 轨道 3 动画：角度 -31° */
@keyframes meteor-track-3 {
  0% { transform: translate(0, 0) rotate(-31deg) scale(0); opacity: 0; }
  4.5% { opacity: 0.9; transform: translate(-300px, 180px) rotate(-31deg) scale(0.95); }
  9% { opacity: 0; transform: translate(-650px, 390px) rotate(-31deg) scale(0); }
  100% { transform: translate(-650px, 390px) rotate(-31deg) scale(0); opacity: 0; }
}

/* 轨道 4 动画：角度 -38° */
@keyframes meteor-track-4 {
  0% { transform: translate(0, 0) rotate(-38deg) scale(0); opacity: 0; }
  3.5% { opacity: 1; transform: translate(-320px, 250px) rotate(-38deg) scale(1); }
  7% { opacity: 0; transform: translate(-640px, 500px) rotate(-38deg) scale(0); }
  100% { transform: translate(-640px, 500px) rotate(-38deg) scale(0); opacity: 0; }
}

/* 轨道 5 动画：角度 -34° */
@keyframes meteor-track-5 {
  0% { transform: translate(0, 0) rotate(-34deg) scale(0); opacity: 0; }
  6% { opacity: 0.85; transform: translate(-450px, 303px) rotate(-34deg) scale(1.15); }
  12% { opacity: 0; transform: translate(-900px, 606px) rotate(-34deg) scale(0); }
  100% { transform: translate(-900px, 606px) rotate(-34deg) scale(0); opacity: 0; }
}

/*全屏清透雾化iMessage风_糯叽机聊天页面美化
