    margin-right: 0 !important;
}

/* 对方消息去掉头像后的左边距调整 */
.msg-bubble-wrapper:has(.bubble-them-custom) {
    margin-left: 0 !important;
}

/* ==========================================
   十一、顶栏整体样式 (高度、灰色背景、无边框与阴影)
========================================== */
:root {
  /* 调整顶栏整体高度 */
  --chat-header-height: 70px; 
  /* 直接修改系统底层变量，强行锁死头像为正圆 */
  --chat-header-avatar-radius: 50%;
  --chat-header-avatar-size: 58px;
}

.chat-header-custom, 
