  color: #333333 !important;
}

/* 2. 【顶栏头像外层框】：只负责定位，去掉边框和投影（改由::after在最顶层绘制） */
.header-avatar-container {
  position: relative !important;
  overflow: visible !important;          /* 确保大圆托底和相框不被切边 */
  z-index: 5 !important;

  /* ▼ 调整【头像整体】的上下左右位置 */
  top: 10px !important;                  
  left: 0px !important;                  

  width: 58px !important;
  height: 58px !important;

  border: none !important;               /* 清空原容器边框 */
  box-shadow: none !important;           /* 清空原容器投影 */
  background: transparent !important;
}

/* 3. 【顶栏头像图片本体】：强制归在【中层】，确保被最顶层的白框盖住 */
.header-avatar-container img,
.header-avatar-container > div,
.chat-header-avatar {
  display: block !important;
  position: relative !important;
  z-index: 2 !important;                 /* 中层：压在灰色托底上方，被白色相框压在下方 */
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;          
  border: none !important;               

  border-radius: 50% !important;         
  overflow: hidden !important;           /* 锁死图片为正圆 */
}

/* 4. 【终极白色头像框与投影】：强制在【顶层】绘制，100% 解决被图片遮挡的问题！ */
.header-avatar-container::after {
  content: "" !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  right: 0 !important;
  bottom: 0 !important;
  z-index: 3 !important;                 /* 顶层：直接盖在头像图片正上方 */
  pointer-events: none !important;       /* 穿透点击，不影响头像点击事件 */

  /* 绘制白色头像框与阴影 */
  border: 2px solid #FFFFFF !important;  
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15) !important; 
  border-radius: 50% !important;         
}

/* ==========================================
   十三、顶栏右侧按钮：隐身点击 + 替换设置图片
========================================== */

/* 1. 隐藏电话和视频按钮，但保证可以点击 */
