  background-repeat: no-repeat !important;
  background-color: transparent !important;

  opacity: 1 !important;                 
  border: none !important;
  width: 24px !important;                
  height: 24px !important;
}

.header-btn-info svg {
  display: none !important;
}

/* ==========================================
   十四、顶栏头像后方：与背景融合的托底半圆弧线 (底层)
========================================== */
.header-avatar-container::before {
  content: "" !important;
  position: absolute !important;
  z-index: 1 !important;                 /* 底层：铺在最下面，作为顶栏向下的延伸托底 */

  /* 必须和顶栏的背景色一模一样 */
  background-color: #F5F5F5 !important;  

  /* ----------------------------------------------------
     ▼ 标注：调整弧形托底的大小和位置
     ---------------------------------------------------- */
  /* 1. 弧形的宽度：数值越大，弧线两边越平缓 */
  width: 100px !important;               

  /* 2. 弧形的高度：决定了弧线的饱满程度 */
  height: 100px !important;              

  /* 3. 保证弧线永远在头像的正中心 */
  left: 50% !important;
  transform: translateX(-50%) !important;

  /* 4. 上下位置控制：
     - 如果您觉得弧线往下包得【不够深】，把负数改小 (如 -20px, -10px)。
     - 如果觉得弧线【太长了】，把负数改大 (如 -40px, -50px)。
  */
  top: -35px !important;                 

  border-radius: 50% !important;         
}
:root {
  /* ==========================================
     我方气泡 (淡粉紫、无边框、缩小、方圆)
  ========================================== */
  --bubble-me-bg: #EEE1EA;
  --bubble-me-bg-gradient: initial;
  --bubble-me-color: #4A3D49;
  --bubble-me-border: none;
  --bubble-me-shadow: 0 1px 3px rgba(0, 0, 0, 0.02);
  --bubble-me-link-color: #8C6A85;

  /* 1. 缩小整体与高度 (调小字号、行高与上下内边距) */
  --bubble-me-font-size: 14px;
  --bubble-me-line-height: 1.35;
  --bubble-me-padding: 7px 12px;

  /* 2. 方圆形外观 (12px外圆角，连发时内侧4px衔接) */
  --bubble-me-radius: 12px;
  --bubble-me-radius-first: 12px 12px 4px 12px;
  --bubble-me-radius-mid: 12px 4px 4px 12px;
  --bubble-me-radius-last: 12px 4px 12px 12px;

  /* ==========================================
     对方气泡 (白色、特定边框、缩小、方圆)
  ========================================== */
  --bubble-them-bg: #FFFFFF;
  --bubble-them-bg-gradient: initial;
  --bubble-them-color: #333333;
  --bubble-them-border: 1px solid #F1ECF0;
  --bubble-them-shadow: 0 1px 2px rgba(0, 0, 0, 0.03);
  --bubble-them-link-color: #8C6A85;

  /* 1. 缩小整体与高度 */
  --bubble-them-font-size: 14px;
  --bubble-them-line-height: 1.35;
  --bubble-them-padding: 7px 12px;

  /* 2. 方圆形外观 */
  --bubble-them-radius: 12px;
  --bubble-them-radius-first: 12px 12px 12px 4px;
  --bubble-them-radius-mid: 4px 12px 12px 4px;
  --bubble-them-radius-last: 4px 12px 12px 12px;

  /* ==========================================
     相关组件同步缩小与适配
  ========================================== */
  --translation-btn-color: #8C6A85;
  --translation-text-color: #555555;
  --translation-bg: rgba(241, 236, 240, 0.5);
  --translation-size: 12.5px;
  --translation-padding: 6px 10px;

  --voice-me-color: #4A3D49;
  --voice-me-bar-active: #4A3D49;
  --voice-me-bar-inactive: rgba(74, 61, 73, 0.25);
  --voice-them-color: #333333;
  --voice-them-bar-active: #8C6A85;
  --voice-them-bar-inactive: #E5E5E5;

  /* 确保全局变量也不会把方圆盖掉 */
  --plain-avatar-radius: 12px;
  --avatar-radius: 12px;
}

/* ==========================================
   一、头像显示逻辑 (隐藏时保留占位，气泡完美对齐)
========================================== */
/* 【我方头像】 */
.msg-avatar-me-container {
  visibility: hidden !important;
}
.msg-avatar-me-container.is-last,
.msg-avatar-me-container.is-single {
  visibility: visible !important;
}

/* 【对方头像】 */
.msg-avatar-them-container {
  visibility: hidden !important;
}
.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single {
  visibility: visible !important;
}

/* ==========================================
   二、【我方头像】对齐与上下左右微调
========================================== */
.msg-avatar-me-container {
  align-self: flex-end !important;
  position: relative !important;
  left: -30px !important;
  top: 40px !important;
  margin-left: 10px !important; 
  overflow: visible !important;          /* 确保底部卡片移位出去时不会被裁剪 */
}

/* ==========================================
   三、【对方头像】对齐与上下左右微调
========================================== */
.msg-avatar-them-container {
  position: relative !important;
  left: 30px !important;
  top: -40px !important;
  margin-right: 10px !important;
  overflow: visible !important;          /* 确保底部卡片移位出去时不会被裁剪 */
}

/* ==========================================
   四、双方消息间距调整 (换人发言时较宽)
========================================= */
.msg-bubble-wrapper.is-last,
.msg-bubble-wrapper.is-single {
  margin-bottom: 30px !important; 
}

/* ==========================================
   五、头像：方圆形 + 白色边框 + 可旋转超大双层底框 (双层独立阴影)
========================================== */

/* 1. 头像本体 (顶层)：方圆形、白边框、第一层阴影 */
.msg-avatar-me-inner,
.msg-avatar-them-inner,
.msg-avatar-custom {
  border-radius: 12px !important;
  border: 2px solid #FFFFFF !important;    /* 第一层：白色实体边框 */

  /* 第一层头像专属阴影 */
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.13) !important; 

  box-sizing: border-box !important;
  position: relative !important;
  z-index: 3 !important;                   /* 顶层压在底层上 */
}

/* 2. 头像底层 (底层)：等比例扩大、第二层白边、投影、可整体移位和旋转 */
.msg-avatar-me-container::before,
.msg-avatar-them-container::before {
  content: "";
  position: absolute;

  /* 底盘默认向外延伸 3px */
  top: -1px !important;
  left: -1px !important;
  right: -1px !important;
  bottom: -1px !important;

  border-radius: 14px !important;          
  background: #FFFFFF !important;          /* 底盘纯白实体 */
  border: 1px solid #E5E5E5 !important;    /* 第二层边框：偏灰细边框 */

  /* 最底部的全局阴影 */
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.10) !important; 

  z-index: 1 !important;                   /* 底盘在下 */
  pointer-events: none !important;

  /* ----------------------------------------------------------------------
     ▼ 标注：【底层白框卡片 + 它自带的投影】整体移位与旋转控制

     参数说明：
     - translateY(-px) : 控制物理位置的【上下移位】（正数向下移动，负数向上移动，例如：translateY(3px)）
     - translateX(0px) : 控制物理位置的【左右移位】（正数向右移动，负数向左移动）
     - rotate(-10deg)   : 控制旋转角度（正数顺时针，负数逆时针）

     您可以任意修改这些数值，让底盘向您希望的方向错落显露。
     ---------------------------------------------------------------------- */
  transform: translateY(-3px) translateX(-3px) rotate(-10deg) !important;     
}
/* ==========================================
   六、对方消息左侧：贯穿竖线与圆点 (修正头像底层冲突)
========================================== */

/* 1. 【安全清理】：只清理可能产生幽灵旧线的 ::after，绝对不碰头像底层的 ::before */
.msg-avatar-them-container::after,
.msg-bubble-wrapper.msg-them::after {
  display: none !important;
  background: none !important;
}

/* 2. 轨道挂载：在每行消息上准备统一的画图容器 */
.msg-bubble-wrapper.msg-them::before {
  content: "" !important;
  position: absolute !important;
  z-index: 10 !important;
  pointer-events: none !important;
  width: 10px !important;            /* 给圆点留足空间 */
  transform: translateX(-50%) !important; /* 确保线绝对居中 */

  /* ----------------------------------------------------------------------
     ▼ 左右移动对齐头像：
     - 请调节这里的数值（比如 40px, 45px, 50px），直到线完美穿过头像正中心！
     ---------------------------------------------------------------------- */
  left: 20px !important; 
}

/* 3. 【第一条消息】：往上超出头像，往下穿透间距 */
.msg-bubble-wrapper.msg-them.is-first::before {
  top: -15px !important;             /* 往上冒出头像 */
  bottom: -35px !important; 

  background: linear-gradient(#EEE1EA, #EEE1EA) no-repeat center top !important;
  background-size: 2px 100% !important;
}

/* 4. 【中间消息】：上下完全打通，负责无缝拼接 */
.msg-bubble-wrapper.msg-them.is-mid::before {
  top: -20px !important; 
  bottom: -35px !important; 

  background: linear-gradient(#EEE1EA, #EEE1EA) no-repeat center top !important;
  background-size: 2px 100% !important;
}

/* 5. 【最后一条消息】：上面接住线，下面画圆点停住 */
.msg-bubble-wrapper.msg-them.is-last::before {
  top: -20px !important; 
  bottom: 10px !important;           /* 决定圆点在哪里停下 */

  background: 
    radial-gradient(circle, #EEE1EA 4px, transparent 4.5px) no-repeat center bottom,
    linear-gradient(#EEE1EA, #EEE1EA) no-repeat center top !important;
  background-size: 8px 8px, 2px calc(100% - 4px) !important;
}

/* 6. 【单条消息】：上面冒出头像，下面画圆点停住 */
.msg-bubble-wrapper.msg-them.is-single::before {
  top: -15px !important;             /* 往上冒出头像 */
  bottom: 10px !important; 

  background: 
    radial-gradient(circle, #EEE1EA 4px, transparent 4.5px) no-repeat center bottom,
    linear-gradient(#EEE1EA, #EEE1EA) no-repeat center top !important;
  background-size: 8px 8px, 2px calc(100% - 4px) !important;
}
/* ==========================================
   七、我方消息右侧：贯穿竖线与顶部圆点 (全新新增)
========================================= */

/* 1. 【安全清理】：防止我方产生多余的幽灵线条 */
.msg-avatar-me-container::after,
.msg-bubble-wrapper.msg-me::after {
  display: none !important;
  background: none !important;
}

/* 2. 轨道挂载：在右侧准备好垂直通道 */
.msg-bubble-wrapper.msg-me::before {
  content: "" !important;
  position: absolute !important;
  z-index: 10 !important;
  pointer-events: none !important;
  width: 10px !important;            /* 给圆点留出空间 */
  transform: translateX(50%) !important;  /* 确保右侧线条绝对居中 */

  /* ----------------------------------------------------------------------
     ▼ 左右移动对齐【我方】头像：(只调这一个值！)
     - 因为您我方头像设置了 left: -30px，所以线也要往左移动寻找头像。
     - 请调节这里的数值（比如 40px, 45px, 50px），直到线完美穿过右侧头像正中心！
     ---------------------------------------------------------------------- */
  right: 20px !important; 
}

/* 3. 【第一条消息】：最上方绘制实心圆点，向下无限延伸穿过间隙 */
.msg-bubble-wrapper.msg-me.is-first::before {
  top: 10px !important;             /* 往上冒出，作为起点的圆点位置 */
  bottom: -50px !important;          /* 向下穿透间距接下一条线 */

  /* 
     双重背景（保证圆点在最顶端，直线在下方）：
     - radial-gradient: 在最顶部 (center top) 绘制一个直径 8px 的 #EEE1EA 实心圆
     - linear-gradient: 在下方 (center bottom) 绘制一条 2px 粗的竖线，避开顶部的圆点
  */
  background: 
    radial-gradient(circle, #EEE1EA 4px, transparent 4.5px) no-repeat center top,
    linear-gradient(#EEE1EA, #EEE1EA) no-repeat center bottom !important;
  background-size: 8px 8px, 2px calc(100% - 4px) !important;
  background-position: center top, center bottom !important; /* 圆在上，线在下 */
}

/* 4. 【中间消息】：纯直线，上下完全打通首尾无缝拼接 */
.msg-bubble-wrapper.msg-me.is-mid::before {
  top: -20px !important; 
  bottom: -35px !important; 

  background: linear-gradient(#EEE1EA, #EEE1EA) no-repeat center top !important;
  background-size: 2px 100% !important;
}

/* 5. 【最后一条消息】：纯直线，从上方接住，往下穿透到我方底部头像中心截止 */
.msg-bubble-wrapper.msg-me.is-last::before {
  top: -20px !important; 
  bottom: 30px !important;           /* 线条向下的截止高度（正好穿过我方头像中心） */

  background: linear-gradient(#EEE1EA, #EEE1EA) no-repeat center top !important;
  background-size: 2px 100% !important;
}

/* 6. 【单条消息】：顶部画圆点，往下穿透到我方底部头像中心截止 */
.msg-bubble-wrapper.msg-me.is-single::before {
  top: 5px !important;             /* 顶部圆点起点 */
  bottom: -20px !important;           /* 底部头像截止 */

  background: 
    radial-gradient(circle, #EEE1EA 4px, transparent 4.5px) no-repeat center top,
    linear-gradient(#EEE1EA, #EEE1EA) no-repeat center bottom !important;
  background-size: 8px 8px, 2px calc(100% - 4px) !important;
  background-position: center top, center bottom !important; /* 圆在上，线在下 */
}
/* ==========================================
   八、终极版：双方头像旁侧标签 (100%锁死方圆 + 找回小字)
========================================== */

/* 1. 【强力锁死】：强行开启图片裁剪，确保头像绝对是方圆形！ */
