  /* ====================================================
     ▼▼▼ 核心修正：负数强制把它提出输入框外部！ ▼▼▼
     数值越负（如 -40px, -45px），离输入框越远
     ==================================================== */
  right: -38px !important;               

  top: 50% !important;
