/* ===================================================
   【🎫 车票内凹打孔气泡美化（深孔+密齿版）】
   =================================================== */

/* 1. 对方气泡：浅灰色 + 方形 + 左侧微型深孔内凹 */
.chat-detail-screen:has(.header-btn-info, .header-btn-phone, .header-btn-video) .bubble-them-custom {
    position: relative !important;
    background: #ececec !important;          /* 对方气泡颜色：浅灰色 */
    color: #2c2c2c !important;               
    border-radius: 4px !important;           /* 车票方形：轻微圆角 */
    border: none !important;
    box-shadow: none !important;

    /* ---------------------------------------------------
       【气泡大小】：高度与字号等比例缩小
       --------------------------------------------------- */
    padding: 7px 12px !important;            
    font-size: 13.5px !important;            
    line-height: 1.35 !important;            

    /* ---------------------------------------------------
       【🌟 对方左侧打孔】：加深圆孔 + 紧密间距
       --------------------------------------------------- */
    /* 3.5px 代表圆孔半径：【数值越大，孔向内凹得越深！】（最大不要超过6px，否则孔会连在一起断开） */
    -webkit-mask-image: radial-gradient(circle at 0px 6px, transparent 3.5px, #000 4px) !important;

    /* 12px 代表孔与孔的间距。6px 必须是它的一半 */
    -webkit-mask-size: 100% 12px !important; 
    -webkit-mask-repeat: repeat-y !important;

    /* 标准浏览器兼容 */
    mask-image: radial-gradient(circle at 0px 6px, transparent 3.5px, #000 4px) !important;
    mask-size: 100% 12px !important;
    mask-repeat: repeat-y !important;
}

/* 2. 我方气泡：深黑色 + 方形 + 右侧微型深孔内凹 */
.chat-detail-screen:has(.header-btn-info, .header-btn-phone, .header-btn-video) .bubble-me-custom {
    position: relative !important;
    background: #1a1a1a !important;          /* 我方气泡颜色：深黑色 */
    color: #ffffff !important;               
    border-radius: 4px !important;           /* 车票方形 */
    border: none !important;
    box-shadow: none !important;

    /* ---------------------------------------------------
       【气泡大小】：高度与字号等比例缩小
       --------------------------------------------------- */
    padding: 7px 12px !important;            
    font-size: 13.5px !important;            
    line-height: 1.35 !important;            

    /* ---------------------------------------------------
       【🌟 我方右侧打孔】：加深圆孔 + 紧密间距
       --------------------------------------------------- */
    /* 3.5px 代表圆孔半径：【数值越大，孔向内凹得越深！】 */
    -webkit-mask-image: radial-gradient(circle at 100% 6px, transparent 3.5px, #000 4px) !important;

    /* 12px 代表孔与孔的间距。6px 必须是它的一半 */
    -webkit-mask-size: 100% 12px !important; 
    -webkit-mask-repeat: repeat-y !important;

    /* 标准浏览器兼容 */
    mask-image: radial-gradient(circle at 100% 6px, transparent 3.5px, #000 4px) !important;
    mask-size: 100% 12px !important;
