    height: 24px !important;                 /* 强制压缩行高 */
    align-items: center !important;
}


/* ================== ★ 2. 语音转文字：点击气泡任意处（避开播放键）直接展开 ★ ================== */

/* 将原本的转写按钮透明化，并平铺覆盖在整张车票上（左侧避开 32px 的播放按钮，防止冲突） */
.chat-detail-screen:has(.header-btn-info, .header-btn-phone, .header-btn-video) .voice-transcription-toggle {
    position: absolute !important;
    top: 0 !important;
    right: 0 !important;
    bottom: 0 !important;
    left: 32px !important;                   /* 👈 留出左侧空间给播放键，其余全屏区域都是点击判定区 */
    width: auto !important;
    height: auto !important;
    opacity: 0 !important;                    /* 100% 隐形，但完全可接收点击 */
    z-index: 10 !important;
    cursor: pointer !important;
    display: flex !important;
}

/* 隐藏转写按钮里的默认文字和图标（防止穿帮） */
.voice-transcription-toggle * {
    display: none !important;
}


/* ================== ★ 3. 语音转文字：展开文本虚线分割排版 ★ ================== */
.voice-transcription {
    /* ---------------------------------------------------
       【虚线隔开 C】：展开文字上边缘加入精致虚线
       --------------------------------------------------- */
    border-top: 1.2px dashed rgba(142, 142, 142, 0.4) !important; /* 虚线分割线 */
    margin-top: 6px !important;
    padding-top: 6px !important;

    background: transparent !important;       /* 彻底清除默认背景色，与票根背景融为一体 */
    border-radius: 0 !important;
    box-shadow: none !important;
    font-size: 12.5px !important;
    line-height: 1.4 !important;
    width: 100% !important;
}

/* 根据气泡底色自适应文字颜色 */
.msg-me .voice-transcription {
    color: #dddddd !important;               /* 我方黑色车票：字用浅灰白 */
}
.msg-them .voice-transcription {
    color: #444444 !important;               /* 对方灰色车票：字用深灰 */
