/* ==========================================================================
   🎬 独立动画模块：新消息渐显入场 & 气泡/转账卡点击Q弹反馈
   ========================================================================== */

/* ================== ★ 1. 新消息发送/展示：渐显微缩入场动画 ★ ================== */

/* 定义车票滑入渐显动画：稍微从下方升起、同时等比例由小变大 */
@keyframes ticketSlideIn {
    from {
        opacity: 0;
        transform: translateY(12px) scale(0.96); /* 从下方 12px、缩放 96% 状态开始 */
    }
    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

/* 将渐显动画绑定到整行消息（包含头像、气泡、转账卡，会一起优雅滑入） */
.msg-bubble-wrapper {
    /* 0.35s 是入场时间；cubic-bezier 提供了极度舒适的减速阻尼感 */
    animation: ticketSlideIn 0.35s cubic-bezier(0.15, 0.85, 0.3, 1) forwards !important;

    /* 启用硬件加速，防止多条消息同时发送时出现任何掉帧、卡顿 */
    will-change: transform, opacity !important; 
}


/* ================== ★ 2. 点击气泡与转账卡：果冻Q弹物理形变动画 ★ ================== */

/* A. 基础状态：为气泡和转账卡加入回弹物理属性 */
.bubble-me-custom,
.bubble-them-custom,
.msg-transfer-card {
    /* ---------------------------------------------------
       【弹性贝塞尔曲线】：cubic-bezier(0.175, 0.885, 0.32, 1.45) 
       这是实现 Q 弹（松开手指时会微微超出原本大小再弹回）的物理公式。
       --------------------------------------------------- */
    transition: transform 0.25s cubic-bezier(0.175, 0.885, 0.32, 1.45), filter 0.15s ease !important;

    /* 确保形变从中轴线向四周扩散，绝对不产生偏斜 */
    transform-origin: center center !important; 

    cursor: pointer !important;
}

/* B. 激活状态（按下/点击气泡、语音、转账卡时） */
.bubble-me-custom:active,
.bubble-them-custom:active,
.msg-transfer-card:active {
    /* ---------------------------------------------------
       【Q弹形变大小】：控制点击时按压下去的“扁平度”
       --------------------------------------------------- */
    transform: scale(0.93) !important;       /* 数值越小，按压下去的凹陷感、Q弹感越猛烈 */

    /* ---------------------------------------------------
       【触觉暗反馈】：手指按下时，气泡微微变暗，提供视觉回馈
       --------------------------------------------------- */
    filter: brightness(0.9) !important;      /* 0.9 代表变暗 10%，松开手会自动恢复原色 */
}


/* ================== ★ 3. 语音波形与文字展开：防抖与过渡平滑 ★ ================== */
.voice-transcription,
.msg-translation-content {
    /* 展开文字时，文字本身也会以渐显方式丝滑展现，防止突兀 */
    animation: fadeIn 0.25s ease-out forwards !important;
}
/* ==========================================================================
   🎫 独立模块：车票风扁平打孔输入框（双侧打孔 + 强制渲染黑色 Reply 票根按钮）
   ========================================================================== */

