/* 4. 强绘制：输入框车票打孔背景（在 ::before 渲染，防止剪裁外部按钮） */
.input-action-bar-custom::before {
    content: "" !important;
    position: absolute !important;
    top: 0 !important;
    bottom: 0 !important;
    left: 0 !important;
    right: 0 !important;
