@keyframes thermalPrint {
    0% {
        clip-path: inset(0 0 100% 0); /* 从底部裁剪掉 100% */
        filter: contrast(1.5) brightness(1.2);
    }
    100% {
        clip-path: inset(0 0 0 0);    /* 完全展开 */
        filter: contrast(1) brightness(1);
    }
}

.bubble-me-custom,
.bubble-them-custom {
    /* 配合之前的渐显，加入打印机裁剪效果，0.4s 干净利落 */
    animation: thermalPrint 0.45s cubic-bezier(0.4, 0, 0.2, 1) forwards !important;
}
@keyframes stampIn {
    0% {
        transform: scale(2.5) rotate(-12deg);
        filter: blur(4px) brightness(1.5);
        opacity: 0;
    }
    70% {
        transform: scale(0.95) rotate(3deg);
        filter: blur(0) brightness(0.9);
        opacity: 1;
    }
    85% {
        transform: scale(1.03) rotate(-1deg);
    }
    100% {
        transform: scale(1) rotate(0deg);
    }
}

/* 绑定到转账卡，让每一张转账卡入场都像盖了钢印一样爽快 */
.msg-transfer-card {
    animation: stampIn 0.45s cubic-bezier(0.25, 0.8, 0.25, 1.25) forwards !important;
}
@keyframes splitFlap {
    0% {
        transform: rotateX(-90deg);
        filter: brightness(0.3) contrast(1.5);
        opacity: 0;
    }
    50% {
        transform: rotateX(20deg);
        filter: brightness(1.2);
    }
    75% {
        transform: rotateX(-10deg);
    }
    100% {
        transform: rotateX(0deg);
        filter: brightness(1) contrast(1);
        opacity: 1;
    }
}
