/* =========================================================
   💬 深黑顶栏 · 微信绿气泡 · 锐利高光质感版
   ========================================================= */
:root {
  /* === 全局背景 === */
  --chat-bg-color: #ffffff;

  /* 顶栏基础变量 */
  --chat-header-height: 56px;

  /* 🎯🎯 主标题(备注)设置 (配合深黑顶栏，改为纯白) 🎯🎯 */
  --chat-header-title-color: #ffffff; 
  --chat-header-title-size: 17px;
  --chat-header-title-weight: 600;
  --title-top-position: 70%; 

  /* 🎯🎯 自定义副标题设置 (改为浅灰白) 🎯🎯 */
  --custom-subtitle-text: "在线"; 
  --custom-subtitle-color: rgba(235, 235, 245, 0.6); 
  --custom-subtitle-size: 11px;
  --custom-subtitle-top: 22px; 

  /* 隐藏系统原生副标题和头像 */
  --chat-header-subtitle-color: transparent;
  --chat-header-subtitle-size: 0px;
  --chat-header-avatar-size: 0px;

  /* === 素净模式布局 === */
  --plain-gap-between-groups: 20px;
  --plain-gap-within-group: 6px;
  --plain-content-max-width: 65%;
  --plain-padding-left-me: 60px;
  --plain-padding-right-me: 0px;
  --plain-padding-left-them: 0px;
  --plain-padding-right-them: 60px;
  --plain-avatar-size: 42px;
  --plain-avatar-radius: 6px;
  --plain-avatar-gap: 10px;

/* 🎯🎯 我方气泡 (低饱和浅玫粉渐变 + 顶部高光) 🎯🎯 */
  --bubble-me-bg: linear-gradient(to bottom, #f5e8f0 0%, #e6cdd8 100%);
  --bubble-me-color: #1a1a1a;
  --bubble-me-padding: 7px 10px;
  --bubble-me-radius: 4px;
  --bubble-me-border: 1px solid #d4b4c4; /* 低饱和度的灰玫粉边框 */
  --bubble-me-shadow: inset 0 1px 0 rgba(255,255,255,0.6), 0 1px 2px rgba(0,0,0,0.05);

  /* 🎯🎯 对方气泡 (保持极浅银灰) 🎯🎯 */
  --bubble-them-bg: linear-gradient(to bottom, #f8f8f8 0%, #e4e4e4 100%);
  --bubble-them-color: #333333;
  --bubble-them-padding: 7px 10px;
  --bubble-them-radius: 4px;
  --bubble-them-border: 1px solid #d4d4d4;
  --bubble-them-shadow: inset 0 1px 0 #ffffff, 0 1px 2px rgba(0,0,0,0.05);
}

/* =========================================================
   🎯🎯 气泡本体应用 (加入高光和阴影) 🎯🎯
   ========================================================= */
.msg-avatar-them-inner, .msg-avatar-me-inner { border-radius: 6px !important; }

.msg-plain-me {
  background: var(--bubble-me-bg) !important;
  color: var(--bubble-me-color) !important;
  padding: var(--bubble-me-padding) !important;
  border-radius: var(--bubble-me-radius) !important;
  border: var(--bubble-me-border) !important;
  box-shadow: var(--bubble-me-shadow) !important; 
}
.msg-plain-them {
  background: var(--bubble-them-bg) !important;
  color: var(--bubble-them-color) !important;
  padding: var(--bubble-them-padding) !important;
  border-radius: var(--bubble-them-radius) !important;
  border: var(--bubble-them-border) !important;
  box-shadow: var(--bubble-them-shadow) !important; 
}

/* ── 对方气泡: 左侧带描边的小尖角 (保持银灰) ── */
.bubble-them-custom { position: relative !important; overflow: visible !important; }
.bubble-them-custom::before {
  content: "" !important; position: absolute !important; left: -7px !important; top: 12px !important;
  border-top: 6px solid transparent !important; border-bottom: 6px solid transparent !important; 
  border-right: 7px solid #d4d4d4 !important; 
  pointer-events: none !important;
}
.bubble-them-custom::after {
  content: "" !important; position: absolute !important; left: -5px !important; top: 13px !important;
  border-top: 5px solid transparent !important; border-bottom: 5px solid transparent !important; 
  border-right: 6px solid #e4e4e4 !important; 
  pointer-events: none !important;
}

/* ── 我方气泡: 右侧带描边的小尖角 (🎯 换成低饱和浅玫粉) ── */
.bubble-me-custom { position: relative !important; overflow: visible !important; }
/* 外层尖角(描边色) */
.bubble-me-custom::before {
  content: "" !important; position: absolute !important; right: -7px !important; top: 12px !important;
  border-top: 6px solid transparent !important; border-bottom: 6px solid transparent !important; 
  border-left: 7px solid #d4b4c4 !important; /* 🎯 灰玫粉边框色 */
  pointer-events: none !important;
}
/* 内层尖角(底色) */
.bubble-me-custom::after {
  content: "" !important; position: absolute !important; right: -5px !important; top: 13px !important;
  border-top: 5px solid transparent !important; border-bottom: 5px solid transparent !important; 
  border-left: 6px solid #e6cdd8 !important; /* 🎯 浅玫粉底色 */
  pointer-events: none !important;
}

