  line-height: 1.15 !important;
  white-space: nowrap !important;
}

.tm-compose-toolbar>.tm-regen-btn:nth-of-type(4)::before {
  content: "Photo" !important;
  font-size: 11px !important;
  color: var(--ao3-link) !important;
